use vstd::prelude::*;

verus! {

/// Given a vector `s` of length `n`, returns the sequence of all non-empty
/// prefixes of `s`.  In particular the result has length `n`, and
/// for each `i < n`, `result[i]` is the length-`(i+1)` vector
/// consisting of `s[0], s[1], …, s[i]`.
fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
    ensures
        // result has exactly as many prefixes as there are elements in `s`
        result.len() == s.len(),
        // for each prefix index `i`, prefix length is `i+1` and
        // prefix[j] == s[j] for 0 <= j < i+1
        forall |i: usize|
            i < result.len() ==>
                result[i].len() == i + 1
                &&
                forall |j: usize|
                    j < result[i].len() ==>
                        result[i][j] == s[j],
{
    let n = s.len();
    let mut result: Vec<Vec<char>> = Vec::with_capacity(n);
    let mut prefix: Vec<char>       = Vec::with_capacity(n);

    // We iterate over each character `c` in `s`.  At the start of
    // iteration k (0‐based), we have processed `k` characters:
    //   prefix.len() == k
    //   result.len() == k
    //   prefix[j] == s[j]  for all j < k
    //   result[j].len() == j+1  and result[j][l] == s[l]
    //     for all j < result.len(), l < result[j].len()
    //
    // Then we push the k‐th character, extend the prefix, clone it,
    // and append it to result, establishing the invariant for k+1.
    for c in s
        invariant
            prefix.len() <= n,
            result.len() == prefix.len(),
            // prefix so far matches s[0..prefix.len()]
            forall |j: usize|
                j < prefix.len() ==>
                    prefix[j] == s[j],
            // each stored prefix in `result` is correct
            forall |j: usize|
                j < result.len() ==>
                    result[j].len() == j + 1
                    &&
                    forall |l: usize|
                        l < result[j].len() ==>
                            result[j][l] == s[l],
        decreases
            n - prefix.len(),
    {
        prefix.push(c);
        result.push(prefix.clone());
    }

    result
}

} // end of `verus!`

